begin;
create or replace function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end;$$;
do $$
declare org uuid:=gen_random_uuid();actor uuid:='99999999-9999-4999-8999-999999999902';conversation uuid:=gen_random_uuid();brief uuid:=gen_random_uuid();version uuid:=gen_random_uuid();connection uuid:=gen_random_uuid();op uuid:=gen_random_uuid();request jsonb;prepared jsonb;quote jsonb;rate jsonb;acceptance jsonb;job jsonb;again jsonb;manifest jsonb;source jsonb;video_request jsonb;total bigint;
begin
 insert into public.organizations(id,name,slug) values(org,'Transactional Design media QA','design-media-qa-'||org::text);
 insert into public.organization_memberships(organization_id,user_id,role,department_id,status) values(org,actor,'operations_admin','design','active');
 insert into public.department_chat_conversations(id,organization_id,department_id,owner_id,title,context_kind) values(conversation,org,'design',actor,'Rollback media QA','department_private');
 insert into public.design_creative_briefs(id,organization_id,visibility,created_by,updated_by) values(brief,org,'private',actor,actor);
 insert into public.design_creative_brief_versions(id,organization_id,creative_brief_id,version_number,content,content_checksum,validation_snapshot,operation_key,created_by) values(version,org,brief,1,'{"title":"Synthetic","purpose":"Test","instructions":"Synthetic local-only image","audience":"QA"}',repeat('a',64),'{"valid":true}',gen_random_uuid(),actor);
 update public.design_creative_briefs set current_version_id=version,frozen_version_id=version,revision=2 where id=brief;
 insert into public.integration_connections(id,organization_id,provider,display_name,secret_name,status,created_by) values(connection,org,'higgsfield','Rollback no-credential fixture','ANKA_HIGGSFIELD_LOCAL_QA_NO_CREDENTIAL','verified',actor);
 insert into private.ai_execution_budget_limits(organization_id,monthly_limit_microusd,spend_guard_mode) values(org,null,'provider_managed');
 request:=jsonb_build_object('organization_id',org,'context',jsonb_build_object('kind','private','id',conversation),'creative_brief_version_id',version,'connector_connection_id',connection,'provider','higgsfield','model_id','higgsfield-ai/soul/v2/standard','settings','{"resolution":"720p","aspect_ratio":"16:9","enhance_prompt":false}'::jsonb,'output_count',1,'input_versions','[]'::jsonb,'prompt_checksum',repeat('0',64));
 prepared:=public.prepare_design_media_request(org,actor,request);request:=prepared->'request';
 perform pg_temp.ok(request->>'prompt_checksum'=encode(sha256(convert_to(prepared->>'prompt','UTF8')),'hex'),'database derives exact confirmed prompt');
 rate:=public.configure_design_media_rate(org,actor,'higgsfield',request->>'model_id',request->'settings',600000,'https://open.higgsfield.ai/pricing#synthetic',clock_timestamp(),clock_timestamp()+interval '1 hour');
 quote:=public.quote_design_media_request(org,actor,request);acceptance:=jsonb_build_object('generate',true,'quote_id',quote->>'id','request_checksum',quote->>'request_checksum','total_max_charge_microusd',600000);

 insert into private.design_media_test_budgets(organization_id) values(org);
 begin perform public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL blocked campaign dispatched';exception when insufficient_privilege then raise notice 'PASS blocked campaign';end;
 perform pg_temp.ok((select consumed_microusd=0 from private.design_media_test_budgets where organization_id=org),'blocked consumes zero');
 perform pg_temp.ok(not exists(select 1 from private.design_media_generation_jobs where organization_id=org),'blocked rolls back new job');
 begin update private.design_media_test_budgets set state='verified',verified_at=clock_timestamp(),verified_until=clock_timestamp()+interval '1 hour',configurations='[{}]' where organization_id=org;raise exception 'FAIL absent evidence';exception when check_violation then raise notice 'PASS no absent evidence';end;
 -- Synthetic review metadata only, in a transaction rolled back below.
 update private.design_media_test_budgets set state='verified',evidence_reference='synthetic offline proof, NOT provider pricing',verified_at=clock_timestamp(),verified_until=clock_timestamp()+interval '1 hour',configurations=jsonb_build_array(jsonb_build_object('provider','higgsfield','model_id',request->>'model_id','settings',request->'settings','output_count',1,'max_charge_microusd',10000000)) where organization_id=org;
 update private.design_media_test_budgets set verified_until=clock_timestamp()-interval '1 second',verified_at=clock_timestamp()-interval '1 hour' where organization_id=org;
 begin perform public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL expired campaign';exception when insufficient_privilege then raise notice 'PASS expired verification';end;
 update private.design_media_test_budgets set verified_at=clock_timestamp(),verified_until=clock_timestamp()+interval '1 hour' where organization_id=org;
 update private.design_media_test_budgets set configurations='[{}]' where organization_id=org;
 begin perform public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL unchecked setting';exception when insufficient_privilege then raise notice 'PASS exact configuration required';end;
 update private.design_media_test_budgets set configurations=jsonb_build_array(jsonb_build_object('provider','higgsfield','model_id',request->>'model_id','settings',request->'settings','output_count',1,'max_charge_microusd',10000000)) where organization_id=org;
 rate:=public.configure_design_media_rate(org,actor,'higgsfield',request->>'model_id',request->'settings',2000000,'https://open.higgsfield.ai/pricing#synthetic-only',clock_timestamp(),clock_timestamp()+interval '1 hour');
 quote:=public.quote_design_media_request(org,actor,request);acceptance:=jsonb_build_object('generate',true,'quote_id',quote->>'id','request_checksum',quote->>'request_checksum','total_max_charge_microusd',2000000);
 job:=public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);
 perform pg_temp.ok(not (job->>'must_not_submit')::boolean,'exact USD2 needs no second confirmation');
 again:=public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);
 perform pg_temp.ok((again->>'must_not_submit')::boolean,'retry must not submit');
 perform pg_temp.ok((select consumed_microusd=2000000 from private.design_media_test_budgets where organization_id=org),'retry debits once');
 perform public.record_design_media_generation(org,actor,(job->>'id')::uuid,(job->>'claim_id')::uuid,'outcome_unknown',null);
 perform pg_temp.ok((select consumed_microusd=2000000 from private.design_media_test_budgets where organization_id=org),'unknown retains full allowance');
 perform public.reconcile_design_media_budget(org,(job->>'id')::uuid,actor,(job->>'claim_id')::uuid,0,'synthetic zero bill; not real provider evidence');
 perform pg_temp.ok((select consumed_microusd=2000000 from private.design_media_test_budgets where organization_id=org),'settlement does not refund lifetime allowance');
 -- Move old accounting to an earlier cycle: lifetime allowance must not reset.
 update private.ai_execution_budget_reservations set cycle_month=(date_trunc('month',clock_timestamp())-interval '1 month')::date where design_media_job_id=(job->>'id')::uuid;
 perform pg_temp.ok((select consumed_microusd=2000000 from private.design_media_test_budgets where organization_id=org),'month boundary does not reset');
 request:=request||jsonb_build_object('model_id','ideogram/v4.0','settings','{"aspect_ratio":"16:9","rendering_speed":"DEFAULT"}'::jsonb);
 prepared:=public.prepare_design_media_request(org,actor,request);request:=prepared->'request';
 update private.design_media_test_budgets set configurations=configurations||jsonb_build_array(jsonb_build_object('provider','higgsfield','model_id',request->>'model_id','settings',request->'settings','output_count',1,'max_charge_microusd',5000000)) where organization_id=org;
 rate:=public.configure_design_media_rate(org,actor,'higgsfield',request->>'model_id',request->'settings',3000000,'https://open.higgsfield.ai/pricing#synthetic-only',clock_timestamp(),clock_timestamp()+interval '1 hour');
 quote:=public.quote_design_media_request(org,actor,request);acceptance:=jsonb_build_object('generate',true,'quote_id',quote->>'id','request_checksum',quote->>'request_checksum','total_max_charge_microusd',3000000);
 begin perform public.claim_design_media_generation(org,actor,gen_random_uuid(),(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL missing above2';exception when insufficient_privilege then raise notice 'PASS above2 confirmation retained';end;
 again:=public.claim_design_media_generation(org,actor,gen_random_uuid(),(quote->>'id')::uuid,request,prepared->>'prompt',acceptance||'{"confirm_above_threshold":true}');
 perform pg_temp.ok((select consumed_microusd=5000000 from private.design_media_test_budgets where organization_id=org),'models share one total');
 rate:=public.configure_design_media_rate(org,actor,'higgsfield',request->>'model_id',request->'settings',5000001,'https://open.higgsfield.ai/pricing#synthetic-only',clock_timestamp(),clock_timestamp()+interval '1 hour');
 quote:=public.quote_design_media_request(org,actor,request);acceptance:=jsonb_build_object('generate',true,'quote_id',quote->>'id','request_checksum',quote->>'request_checksum','total_max_charge_microusd',5000001,'confirm_above_threshold',true);
 begin perform public.claim_design_media_generation(org,actor,gen_random_uuid(),(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL unverified bound';exception when insufficient_privilege then raise notice 'PASS above verified maximum denied';end;
 rate:=public.configure_design_media_rate(org,actor,'higgsfield',request->>'model_id',request->'settings',5000000,'https://open.higgsfield.ai/pricing#synthetic-only',clock_timestamp(),clock_timestamp()+interval '1 hour');
 quote:=public.quote_design_media_request(org,actor,request);acceptance:=jsonb_build_object('generate',true,'quote_id',quote->>'id','request_checksum',quote->>'request_checksum','total_max_charge_microusd',5000000,'confirm_above_threshold',true);
 again:=public.claim_design_media_generation(org,actor,gen_random_uuid(),(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);
 perform pg_temp.ok((select consumed_microusd=10000000 from private.design_media_test_budgets where organization_id=org),'exact USD10 boundary allowed');
 begin perform public.claim_design_media_generation(org,actor,gen_random_uuid(),(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL lifetime overspend';exception when numeric_value_out_of_range then raise notice 'PASS above shared USD10 denied';end;
 perform pg_temp.ok((select count(*)=3 and sum(amount_microusd)=10000000 from private.design_media_test_debits where organization_id=org),'three immutable debits sum exact total');
 begin update private.design_media_test_budgets set consumed_microusd=0 where organization_id=org;raise exception 'FAIL reset';exception when insufficient_privilege then raise notice 'PASS no reset';end;
 begin delete from private.design_media_test_budgets where organization_id=org;raise exception 'FAIL delete';exception when insufficient_privilege then raise notice 'PASS no delete';end;
 begin update private.design_media_test_debits set amount_microusd=1 where organization_id=org;raise exception 'FAIL refund';exception when insufficient_privilege then raise notice 'PASS no debit rewrite';end;
 begin truncate private.design_media_test_debits;raise exception 'FAIL truncate';exception when insufficient_privilege then raise notice 'PASS no truncate';end;
 perform pg_temp.ok(not has_table_privilege('service_role','private.design_media_test_budgets','insert,update,delete,truncate'),'no service table write grants');
 perform pg_temp.ok(not has_table_privilege('authenticated','private.design_media_test_debits','select,insert,update,delete'),'no user ledger access');
 perform pg_temp.ok(not has_function_privilege('service_role','private.reserve_design_media_test_budget()','execute'),'no direct reserve bypass');
end;$$;
rollback;
